#!/usr/bin/env python3
"""DESIGN-time satisfiability probe for EXP-RUNTIME-38166224613.

Session-Binding-Amortized (SBA) credential-free substrate class.
This probe is NON-OUTCOME-BEARING: it verifies construction invariants, treatment
liveness on a single session per (arm, novelty band), and the closed-form
pre-freeze dynamic-range certificate arithmetic. It does NOT run the scored
20-session matrix that produces the scientific measurement.

stdlib only. deterministic. Run twice must be byte-identical.
"""
from __future__ import annotations

import hashlib
import json
import sys
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.request import Request, urlopen
from urllib.error import HTTPError

RUN_SEED = "SPIDER-RUNTIME-SBA-2026"
FAMILIES = ["F1-RECORDS", "F2-WIDGETS"]
K = 8
NOVELTIES = [0.0, 0.25, 0.5, 0.75]
# frozen judge threshold for the certificate lower band
COMPARATOR_MAX = 0.95
CORRECTNESS_FLOOR = 0.80


def h(*parts) -> str:
    return hashlib.sha256("|".join(str(p) for p in parts).encode()).hexdigest()


def server_secret() -> str:
    return h(RUN_SEED, "server_secret")[:32]


def session_token(family: str, novelty: float, session_index: int) -> str:
    return h(server_secret(), family, novelty, session_index, "token")[:16]


def binding(family: str, novelty: float, session_index: int) -> str:
    # 48-bit one-time session binding
    return h(server_secret(), family, novelty, session_index, "binding")[:12]


def schema_epoch(family: str, novelty: float, session_index: int) -> str:
    return h(server_secret(), family, novelty, session_index, "schema")[:8]


def chain_index(novelty: float) -> int:
    return K - 3 if novelty == 0.5 else K - 1


def precursor_index(novelty: float) -> int:
    return K - 4 if novelty == 0.5 else K - 3


def requires_schema(novelty: float) -> bool:
    return novelty >= 0.25


def expected_resource(family: str, novelty: float, i: int, bind: str):
    if novelty >= 0.5 and i == chain_index(novelty):
        return bind  # only the one-time binding satisfies this task
    return f"{family}-res-{i:03d}"


# ---------------------------------------------------------------------------
# In-memory substrate server (real stdlib HTTP for transport invariants)
# ---------------------------------------------------------------------------
class Substrate:
    def __init__(self):
        self.committed = set()          # (family,novelty,session,i)
        self.binding_used = set()       # (family,novelty,session)
        self.revealed = set()           # (family,novelty,session)

    def session_get(self, family, novelty, si):
        return 200, {
            "session_token": session_token(family, novelty, si),
            "schema_epoch": schema_epoch(family, novelty, si),
            "epoch": "v1",
        }

    def task_get(self, family, novelty, si, i, token):
        if token != session_token(family, novelty, si):
            return 400, {"error": "bad_session"}
        chain = novelty >= 0.5 and i == chain_index(novelty)
        return 200, {
            "index": i,
            "requires_schema": requires_schema(novelty),
            "resource_id": None if chain else f"{family}-res-{i:03d}",
            "is_chain": chain,
        }

    def commit(self, family, novelty, si, i, payload):
        token = payload.get("session_token")
        if token != session_token(family, novelty, si):
            return 400, {"error": "bad_session"}
        if not (0 <= i < K):
            return 400, {"error": "bad_index"}
        key = (family, novelty, si, i)
        if key in self.committed:
            return 409, {"error": "already_committed"}  # no re-reveal
        if requires_schema(novelty) and payload.get("schema_epoch") != schema_epoch(family, novelty, si):
            return 400, {"error": "schema_required"}
        bind = binding(family, novelty, si)
        want = expected_resource(family, novelty, i, bind)
        if payload.get("resource_id") != want:
            return 400, {"error": "bad_resource"}
        chain = novelty >= 0.5 and i == chain_index(novelty)
        if chain:
            if (family, novelty, si) in self.binding_used:
                return 400, {"error": "binding_consumed"}
            self.binding_used.add((family, novelty, si))
        self.committed.add(key)
        receipt = {"status": "ok", "task_index": i}
        if novelty >= 0.5 and i == precursor_index(novelty) and (family, novelty, si) not in self.revealed:
            # one-time reveal of the chain binding in the precursor receipt
            receipt["chain_resource_id"] = bind
            self.revealed.add((family, novelty, si))
        return 200, receipt


SUB = Substrate()


class Handler(BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass

    def _send(self, code, obj):
        body = json.dumps(obj, sort_keys=True).encode()
        self.send_response(code)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        parts = self.path.strip("/").split("/")
        if len(parts) == 4 and parts[:3] == ["api", "v1", "session"]:
            code, obj = SUB.session_get(parts[3], NOVELTIES[2], 0)
            # path encodes novelty via query? keep simple: session by family only
            self._send(code, obj)
            return
        self._send(404, {"error": "not_found"})

    def do_POST(self):
        length = int(self.headers.get("content-length", "0"))
        payload = json.loads(self.rfile.read(length) or b"{}")
        self._send(200, {"echo": True, **payload})


def start_server():
    srv = ThreadingHTTPServer(("127.0.0.1", 0), Handler)
    return srv


# ---------------------------------------------------------------------------
# Arm policies (counter profiles) executed directly against the substrate model
# ---------------------------------------------------------------------------
def run_arm(arm, family, novelty, si):
    """Returns (successes, counters). counters = http, retrieval, verification, repair."""
    bind = binding(family, novelty, si)
    epoch = schema_epoch(family, novelty, si)
    token = session_token(family, novelty, si)
    http = ret = ver = rep = 0
    ok = 0
    held_binding = None
    if arm == "T-AMORTIZED-DISCOVERY":
        http += 1  # one session GET, retained for the whole session
        for i in range(K):
            http += 1  # task GET
            code, body = SUB.task_get(family, novelty, si, i, token)
            if code != 200:
                continue
            rid = body["resource_id"]
            if body["is_chain"]:
                rid = held_binding
            code, receipt = SUB.commit(family, novelty, si, i, {
                "session_token": token, "schema_epoch": epoch, "resource_id": rid})
            http += 1
            ver += 1
            if code == 200:
                ok += 1
                # one-time session binding is revealed in the precursor receipt
                if i == precursor_index(novelty) and novelty >= 0.5 and "chain_resource_id" in receipt:
                    held_binding = receipt["chain_resource_id"]
            else:
                rep += 1
    elif arm in ("B-COLD-RE-DERIVE", "B-RETRIEVAL-SHAPED"):
        for i in range(K):
            http += 1  # session GET before every task, context discarded
            s = SUB.session_get(family, novelty, si)
            if arm == "B-RETRIEVAL-SHAPED":
                ret += 1  # retrieve nearest prior-session receipt (stale binding)
            http += 1  # task GET
            code, body = SUB.task_get(family, novelty, si, i, token)
            if code != 200:
                continue
            rid = body["resource_id"]
            if body["is_chain"]:
                # memoryless-per-task: no retained in-session binding
                rid = None
            code, receipt = SUB.commit(family, novelty, si, i, {
                "session_token": token, "schema_epoch": epoch, "resource_id": rid})
            http += 1
            ver += 1
            if code == 200:
                ok += 1
            else:
                if body["is_chain"]:
                    rep += 1
                    http += 1  # one repair reattempt, still no binding -> 400
                    ver += 1
    elif arm == "PC-EXACT-REPLAY":
        http += 1
        for i in range(K):
            http += 1
            _, body = SUB.task_get(family, novelty, si, i, token)
            rid = bind if body["is_chain"] else body["resource_id"]
            code, receipt = SUB.commit(family, novelty, si, i, {
                "session_token": token, "schema_epoch": epoch, "resource_id": rid})
            http += 1
            ver += 1
            if code == 200:
                ok += 1
    return ok, {"http_calls": http, "retrieval_calls": ret, "verification_calls": ver, "repair_calls": rep}


# ---------------------------------------------------------------------------
# Closed-form certificate + branch reachability
# ---------------------------------------------------------------------------
ARMS = ["T-AMORTIZED-DISCOVERY", "B-COLD-RE-DERIVE", "B-RETRIEVAL-SHAPED", "PC-EXACT-REPLAY"]


def comparator_rate(K):
    return (K - 1) / K


def k_sweep():
    return {str(k): comparator_rate(k) for k in (7, 8, 9, 10)}


def in_band(rate):
    return CORRECTNESS_FLOOR <= rate < COMPARATOR_MAX


def mechanism_off_rate(K):
    # binding exposed via /session -> COLD can satisfy the chain task
    return 1.0


def classify(world):
    if not world.get("validity_gates_pass", True):
        return "MEASUREMENT_INVALID"
    if world.get("leak") or not world.get("liveness", True):
        return "MIXED"
    fams = world.get("families", {})
    certified = [f for f, d in fams.items()
                 if d["cold"] < COMPARATOR_MAX and d["retrieval"] < COMPARATOR_MAX
                 and d["min_correctness"] >= CORRECTNESS_FLOOR and d["distinction"]]
    if certified:
        return "SUPPORTS"
    if fams and all(d["cold"] >= COMPARATOR_MAX for d in fams.values()):
        return "FALSIFIES"
    return "MIXED"


def main():
    out = {"probe": "SBA-pre-freeze-satisfiability", "experiment_id": "EXP-RUNTIME-38166224613",
           "seed": RUN_SEED, "checks": {}, "arm_liveness": {}, "certificate": {}}

    # -- transport smoke over real stdlib HTTP --
    srv = start_server()
    port = srv.server_address[1]
    import threading
    t = threading.Thread(target=srv.serve_forever, daemon=True)
    t.start()
    ok_transport = True
    try:
        with urlopen(f"http://127.0.0.1:{port}/api/v1/session/F1-RECORDS", timeout=5) as r:
            body = json.loads(r.read())
            ok_transport = r.status == 200 and "session_token" in body
    except Exception:
        ok_transport = False
    srv.shutdown()
    out["checks"]["transport_stdlib_http"] = ok_transport

    # -- protocol invariants --
    fam, nov, si = "F1-RECORDS", 0.5, 0
    tok = session_token(fam, nov, si)
    ep = schema_epoch(fam, nov, si)
    bi = binding(fam, nov, si)
    sg = SUB.session_get(fam, nov, si)
    inv = {}
    inv["session_never_reveals_binding"] = "chain_resource_id" not in sg[1] and bi not in json.dumps(sg[1])
    tg = SUB.task_get(fam, nov, si, chain_index(nov), tok)
    inv["chain_task_resource_null"] = tg[1]["resource_id"] is None and tg[1]["is_chain"] is True
    pc, pbody = SUB.commit(fam, nov, si, precursor_index(nov), {
        "session_token": tok, "schema_epoch": ep,
        "resource_id": expected_resource(fam, nov, precursor_index(nov), bi)})
    inv["precursor_reveals_binding_once"] = pc == 200 and pbody.get("chain_resource_id") == bi
    pc2, pbody2 = SUB.commit(fam, nov, si, precursor_index(nov), {
        "session_token": tok, "schema_epoch": ep,
        "resource_id": expected_resource(fam, nov, precursor_index(nov), bi)})
    inv["precursor_recommit_409_no_reveal"] = pc2 == 409 and "chain_resource_id" not in pbody2
    wc, wbody = SUB.commit(fam, nov, si, chain_index(nov), {
        "session_token": tok, "schema_epoch": ep, "resource_id": "F1-RECORDS-res-000"})
    inv["wrong_binding_400_no_leak"] = wc == 400 and bi not in json.dumps(wbody)
    cc, cbody = SUB.commit(fam, nov, si, chain_index(nov), {
        "session_token": tok, "schema_epoch": ep, "resource_id": bi})
    inv["correct_binding_200"] = cc == 200
    rc, rbody = SUB.commit(fam, nov, si, chain_index(nov), {
        "session_token": tok, "schema_epoch": ep, "resource_id": bi})
    inv["binding_consumed_on_reuse"] = rc in (400, 409) and bi not in json.dumps(rbody)
    out["checks"]["protocol_invariants"] = inv
    out["checks"]["all_protocol_invariants_pass"] = all(inv.values())

    # -- treatment liveness + arm vectors on one fresh session per arm/novelty --
    defect = 0.0
    live = True
    for arm in ARMS:
        out["arm_liveness"][arm] = {}
        for novelty in NOVELTIES:
            SUB2 = Substrate()
            globals()["SUB"] = SUB2
            n_ok, counters = run_arm(arm, "F1-RECORDS", novelty, 100)
            out["arm_liveness"][arm][str(novelty)] = {"successes": n_ok, "rate": n_ok / K,
                                                      "counters": counters}
            if arm == "T-AMORTIZED-DISCOVERY" and n_ok != K:
                live = False
            if arm == "PC-EXACT-REPLAY" and n_ok != K:
                defect += 1
    globals()["SUB"] = SUB
    out["checks"]["treatment_live_all_novelties"] = live

    # -- closed form + band bounds --
    cf = {}
    for k in (7, 8, 9, 10):
        cf[str(k)] = {"comparator_rate": comparator_rate(k), "in_band": in_band(comparator_rate(k))}
    out["certificate"]["closed_form"] = cf
    out["certificate"]["k_sweep_all_in_band"] = all(v["in_band"] for v in cf.values())
    out["certificate"]["no_rate_collides_with_095"] = all(abs(comparator_rate(k) - COMPARATOR_MAX) > 1e-12 for k in (7, 8, 9, 10))
    out["certificate"]["no_rate_collides_with_floor"] = all(abs(comparator_rate(k) - CORRECTNESS_FLOOR) > 1e-12 for k in (7, 8, 9, 10))

    # -- binding uniqueness over scored matrix (2*4*20 = 160 sessions) --
    binds = [binding(f, nv, s) for f in FAMILIES for nv in NOVELTIES for s in range(20)]
    out["certificate"]["scored_sessions"] = len(binds)
    out["certificate"]["bindings_distinct"] = len(set(binds)) == len(binds)
    out["certificate"]["binding_bits"] = 48

    # -- mechanism-off control flips the certificate to FALSE --
    out["certificate"]["mechanism_off_cold_rate"] = mechanism_off_rate(K)
    out["certificate"]["mechanism_off_destroys_certificate"] = not (mechanism_off_rate(K) < COMPARATOR_MAX)

    # -- distinction: >= 2/4 counters differ T vs each comparator --
    def counters(arm, novelty="0.5"):
        return out["arm_liveness"][arm][novelty]["counters"]
    diffs = {}
    for other in ("B-COLD-RE-DERIVE", "B-RETRIEVAL-SHAPED"):
        diffs[other] = sum(1 for kk in counters("T-AMORTIZED-DISCOVERY")
                           if counters("T-AMORTIZED-DISCOVERY")[kk] != counters(other)[kk])
    out["certificate"]["counter_diffs_vs_T"] = diffs
    out["certificate"]["arm_identification_ok"] = all(v >= 2 for v in diffs.values())
    out["certificate"]["success_margin_at_0.5"] = out["arm_liveness"]["T-AMORTIZED-DISCOVERY"]["0.5"]["rate"] - out["arm_liveness"]["B-COLD-RE-DERIVE"]["0.5"]["rate"]

    # -- branch reachability --
    good = {"families": {"F1-RECORDS": {"cold": 0.875, "retrieval": 0.875, "min_correctness": 1.0, "distinction": True},
                         "F2-WIDGETS": {"cold": 0.875, "retrieval": 0.875, "min_correctness": 1.0, "distinction": True}},
            "validity_gates_pass": True, "liveness": True, "leak": False}
    ceiling = {"families": {"F1-RECORDS": {"cold": 1.0, "retrieval": 1.0, "min_correctness": 1.0, "distinction": True},
                            "F2-WIDGETS": {"cold": 1.0, "retrieval": 1.0, "min_correctness": 1.0, "distinction": True}},
               "validity_gates_pass": True, "liveness": True, "leak": False}
    leaky = dict(good); leaky = json.loads(json.dumps(good)); leaky["leak"] = True
    invalid = json.loads(json.dumps(good)); invalid["validity_gates_pass"] = False
    branch_map = {"SUPPORTS": classify(good), "FALSIFIES": classify(ceiling),
                  "MIXED": classify(leaky), "MEASUREMENT_INVALID": classify(invalid)}
    out["certificate"]["branch_reachability"] = branch_map
    out["certificate"]["all_branches_inhabited"] = (branch_map["SUPPORTS"] == "SUPPORTS"
                                                    and branch_map["FALSIFIES"] == "FALSIFIES"
                                                    and branch_map["MIXED"] == "MIXED"
                                                    and branch_map["MEASUREMENT_INVALID"] == "MEASUREMENT_INVALID")

    out["checks"]["defect_sessions"] = defect
    out["checks"]["certificate_satisfiable"] = (out["checks"]["all_protocol_invariants_pass"]
                                                and out["checks"]["treatment_live_all_novelties"]
                                                and out["certificate"]["k_sweep_all_in_band"]
                                                and out["certificate"]["bindings_distinct"]
                                                and out["certificate"]["mechanism_off_destroys_certificate"]
                                                and out["certificate"]["arm_identification_ok"]
                                                and out["certificate"]["all_branches_inhabited"]
                                                and out["checks"]["transport_stdlib_http"])
    print(json.dumps(out, indent=2, sort_keys=True))
    return 0 if out["checks"]["certificate_satisfiable"] else 1


if __name__ == "__main__":
    sys.exit(main())
